def remove_duplicate_battle_turn_actions(apps, schema_editor):
    BattleAction = apps.get_model('creature', 'BattleAction')
    duplicate_turns = (
        BattleAction.objects.values('battle_id', 'turn_number')
        .annotate(action_count=Count('id'))
        .filter(action_count__gt=1)
    )
    for duplicate in duplicate_turns.iterator():
        action_ids = list(
            BattleAction.objects.filter(
                battle_id=duplicate['battle_id'],
                turn_number=duplicate['turn_number'],
            )
            .order_by('timestamp', 'pk')
            .values_list('pk', flat=True)
        )
        BattleAction.objects.filter(pk__in=action_ids[1:]).delete()


